    distractors: ['走'],
    wrongVi: ['Chiều mai chúng tôi mới đi.', 'Hôm qua 7 giờ chúng tôi đã xuất phát.', '7 giờ sáng mai ai đi cùng chúng tôi?'],
    wrongZh: ['我们出发明天早上七点半。', '明天早上七点半出发我们。', '我们七点半明天早上出发。']
