    tokens: ['我', '吃了早饭', '就', '去学校', '。'],
    grammarNote: 'Cấu trúc V1 + 了... 就 + V2: Hành động thứ hai diễn ra ngay sau khi hành động thứ nhất kết thúc.',
    distractors: ['才'],
